"""Produce the complete experiment report after analysis and integrity validation."""
import json,hashlib
from pathlib import Path
P=Path(__file__).resolve().parent
a=json.loads((P/'analysis.json').read_text());v=json.loads((P/'integrity_report.json').read_text());assert a['analysis_status']=='complete' and v['checks_passed'] and v['successful_verifications']==1470
lines=['# Matched reference experiment results','','All 294 reference-generation jobs and all 1,470 verification jobs are complete across 147 canonical tasks and five verifiers. Results are from a new experiment; they do not reconstruct the original missing reference inputs.','','## Direct paired accuracy comparison','','| Verifier | Joint valid n | With criteria | Task-only | Difference pp | Paired 95% CI pp | Raw p | Bonferroni p | Holm p |','|---|---:|---:|---:|---:|---|---:|---:|---:|']
for r in a['results']:
 lines.append(f"| {r['model']} | {r['n_joint']} | {100*r['criteria_accuracy']:.1f}% | {100*r['task_only_accuracy']:.1f}% | {r['difference_pp']:+.1f} | [{r['ci95_low_pp']:.1f}, {r['ci95_high_pp']:.1f}] | {r['p_raw']:.4f} | {r['p_bonferroni']:.4f} | {r['p_holm']:.4f} |")
sig=[r['model'] for r in a['results'] if r['p_bonferroni']<.05];raw=[r['model'] for r in a['results'] if r['p_raw']<.05]
lines+=['',f"Comparisons significant after Bonferroni: {', '.join(sig) if sig else 'none'}. Comparisons significant before correction: {', '.join(raw) if raw else 'none'}.",'','Differences are criteria-enriched minus task-only accuracy on the same jointly valid tasks per verifier. Intervals are paired bootstrap percentile intervals from 10,000 resamples (seed 20260927); they are not simultaneous intervals. McNemar uses the two-sided exact binomial test for fewer than 25 discordant pairs and continuity-corrected asymptotic testing otherwise. Bonferroni and Holm cover all five planned comparisons. The contingency cells and matched IDs accompany the CSV.','','## Coverage and operational accuracy','','| Verifier | Criteria valid /147 | Task-only valid /147 | Criteria all-task accuracy | Task-only all-task accuracy | Criteria success F1 | Task-only success F1 |','|---|---:|---:|---:|---:|---:|---:|']
for r in a['results']:
 lines.append(f"| {r['model']} | {r['with_criteria_valid']} | {r['task_only_valid']} | {100*r['with_criteria_all_task_accuracy']:.1f}% | {100*r['task_only_all_task_accuracy']:.1f}% | {r['with_criteria_success_f1']:.3f} | {r['task_only_success_f1']:.3f} |")
lines+=['','All-task accuracy uses 147 as denominator and counts invalid verdicts as unsuccessful verification. Success F1 uses valid responses within each arm and can therefore have differing samples. Invalid verdicts were retained and never retried to obtain a preferred answer. Explicit API failures were logged separately and retried as described in PROTOCOL.md.','','## Interpretation','','This is the direct same-generator control requested by Reviewer 2 Concern 2. The only generation-input difference is inclusion of benchmark evaluation criteria; the wrapper, generator configuration, task, screenshot, verifier prompt and within-provider settings are held fixed. Exact prompts and returned generator/verifier model IDs are retained.','', 'Nonsignificance does not establish equivalence or show that task-only references are ineffective. The older causal statement that evaluation criteria are the primary cause of the text-reference benefit is not justified by this completed control. No fresh no-reference arm was included, so the control does not estimate a new A-to-B benefit. Keep historical and new results separate, and describe criteria-enriched references as supplying target information that may be absent from the user instruction. Deployment recommendations depend on the availability of trustworthy criteria.','','## Integrity and provenance','','All output-to-input integrity checks passed. Records preserve raw responses, exact textual requests, request and returned model identifiers, timestamps, token usage, reference hashes and screenshot hashes. All 147 agent final images were recovered from the user-supplied public trajectory archive using the historical final-embedded-image rule. Of these, 146 are 1280 by 2048 and vwa_shopping_310 is 844 by 393; the same unchanged image is used in both arms.', '',f"Verification attempts: {a['verification_calls']}, including {a['failed_attempts']} failed API attempts. Successful verification responses: 1,470. Generation calls: 294. Conservative cumulative accounting estimate: ${a['cost_upper_estimate_usd']:.2f}; this includes a $0.10 reserve for each failed call and is not an actual provider invoice.",'','The original four missing-reference IDs remain unrecovered. Historical code inserts an empty reference instead of dropping such tasks. A separate exhaustive exclusion sensitivity analysis shows that removing any up to four records cannot eliminate the four retained historical GPT/Claude A-to-B significances after 30-test Bonferroni correction. That exclusion bound does not recover the original inputs or predict outcomes under replacement references.','','Files: paired_results.csv, analysis.json, integrity_report.json, generation_requests.jsonl, generation_results.jsonl, verification_schedule.jsonl, verification_results.jsonl, tasks.jsonl, screenshot_recovery.json, field_examples.json, PROTOCOL.md. Credentials are stored outside this experiment directory and must never be included in a research release.']
(P/'RESULTS.md').write_text('\n'.join(lines)+'\n');print(P/'RESULTS.md')
